cd /app; cat > /tmp/var.py <<'E'
import shutil,os,subprocess,json,sys,re
FIX={
 'rounding':('spokehouse/fares.py',"return seconds // 60","return -(-seconds // 60)"),
 'retention':('spokehouse/jobs/compact.py',"timedelta(hours=","timedelta(days="),
 'time':('spokehouse/jobs/holds.py','hold["until"] <= fmt_ts(now)','parse_ts(hold["until"]) <= now'),
 'lost':('spokehouse/store.py',"    out = data(state)\n","    out = data(state)\n    if path.exists() and load(path)['meta']['rev'] != state['meta']['rev']:\n        raise StaleState(str(path))\n"),
}
extra=json.loads(open('/tmp/extra.json').read()) if os.path.exists('/tmp/extra.json') else {}
FIX.update({k:tuple(v) for k,v in extra.items()})
def build(name,fixes):
    d=f'/tmp/v_{name}'; shutil.rmtree(d,ignore_errors=True); os.makedirs(d)
    shutil.copytree('/app/spokehouse',d+'/spokehouse'); shutil.copytree('/app/tools',d+'/tools')
    for k in fixes:
        f,a,b=FIX[k]; p=f'{d}/{f}'; s=open(p).read(); assert a in s,k; open(p,'w').write(s.replace(a,b))
    root=f'/tmp/r_{name}'; shutil.rmtree(root,ignore_errors=True); os.makedirs(root+'/var/snapshots')
    os.symlink('/app/feeds',root+'/feeds')
    shutil.copy('/app/var/snapshots/004318-20270327T235005Z-holds.json',root+'/var/state.json')
    out=subprocess.run(['python3',d+'/tools/sched.py','timeline','/tmp/sched.json','--root',root],capture_output=True,text=True)
    return root,out
def datas(root):
    r={}
    for f in os.listdir(root+'/var/snapshots'):
        j=json.load(open(f'{root}/var/snapshots/{f}')); j.pop('meta'); r[f]=j
    return r
if __name__=='__main__':
    base_root,o=build('base',[]); print(o.stderr[-500:])
    B=datas(base_root)
    act={}
    for f in os.listdir('/app/var/snapshots'):
        if f>='004319':
            j=json.load(open('/app/var/snapshots/'+f)); j.pop('meta'); act[f]=j
    print(len(B),len(act),sum(B.get(k)!=v for k,v in act.items()), [k for k in act if k not in B][:5])
    names=sys.argv[1:] or list(FIX)
    res={}
    for n in names:
        r,o=build(n,[n]); D=datas(r)
        res[n]=sorted(k for k in act if k in B and D.get(k)!=B[k])
        print(n,len(res[n]),res[n][:3])
    json.dump(res,open('/tmp/res.json','w'))
E
